    public enum FamilyTier implements Tier {
        // tiers repair through the tag quantumfalcon:repairs/<tier> (the ingot each tool
        // is made from); QUANTUM and ECHO sit at diamond level so they are an upgrade once the diamond-priced portal is lit
        CHAOS(BlockTags.INCORRECT_FOR_DIAMOND_TOOL, 1800, 8.5f, 3.5f, 15, "chaos"),
        CRYSTAL(BlockTags.INCORRECT_FOR_IRON_TOOL, 700, 7.0f, 2.5f, 18, "crystal"),
        ECHO(BlockTags.INCORRECT_FOR_DIAMOND_TOOL, 1200, 7.5f, 2.5f, 16, "echo"),
        PHASE(BlockTags.INCORRECT_FOR_DIAMOND_TOOL, 1300, 8.0f, 3.0f, 17, "phase"),
        QUANTUM(BlockTags.INCORRECT_FOR_DIAMOND_TOOL, 1600, 8.0f, 3.0f, 20, "quantum"),
        QUANTUM_BRONZE(BlockTags.INCORRECT_FOR_IRON_TOOL, 400, 6.0f, 2.0f, 14, "quantum_bronze"),
        RESONANCE(BlockTags.INCORRECT_FOR_DIAMOND_TOOL, 1500, 8.0f, 3.0f, 19, "resonance"),
        TEMPORAL(BlockTags.INCORRECT_FOR_NETHERITE_TOOL, 2000, 9.0f, 4.0f, 22, "temporal"),
        VOID(BlockTags.INCORRECT_FOR_NETHERITE_TOOL, 2200, 9.0f, 4.5f, 15, "void"),
        PROBABILITY(BlockTags.INCORRECT_FOR_DIAMOND_TOOL, 1400, 8.0f, 3.0f, 25, "probability"),
        SINGULARITY(BlockTags.INCORRECT_FOR_NETHERITE_TOOL, 2600, 10.0f, 5.0f, 18, "singularity");
        private final TagKey<Block> incorrect; private final int uses; private final float speed, damage; private final int ench; private final String repair;
        FamilyTier(TagKey<Block> incorrect, int uses, float speed, float damage, int ench, String repair) {
            this.incorrect = incorrect; this.uses = uses; this.speed = speed; this.damage = damage; this.ench = ench; this.repair = repair;
        }
        @Override public int getUses() { return uses; }
        @Override public float getSpeed() { return speed; }
        @Override public float getAttackDamageBonus() { return damage; }
        @Override public TagKey<Block> getIncorrectBlocksForDrops() { return incorrect; }
        @Override public int getEnchantmentValue() { return ench; }
        @Override public Ingredient getRepairIngredient() {
            return Ingredient.of(net.minecraft.tags.TagKey.create(net.minecraft.core.registries.Registries.ITEM, ResourceLocation.fromNamespaceAndPath(QuantumFalcon.MOD_ID, "repairs/" + repair)));
        }
    }

